css:
.sl__rule { display: block; width: 50px; height: 3px; border-radius: 2px; background: var(--os-color-accent); margin-bottom: var(--os-space-md); }
.sl__h { margin: 0 0 var(--os-space-lg); }
.sl__item { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2.3fr); gap: var(--os-space-lg); padding-block: var(--os-space-lg); border-top: 1px solid color-mix(in srgb, var(--os-color-text) 22%, transparent); }
.sl__day { margin: 0; font-family: var(--os-font-heading); font-size: 2.4rem; line-height: 1.1; color: var(--os-color-heading); }
.sl__meta { margin: .4rem 0 0; font-size: .9rem; line-height: 1.4; color: var(--os-color-text-muted); }
.sl__next { display: block; }
.sl__next b { color: var(--os-color-link); }
.sl__title { margin: 0 0 var(--os-space-sm); }
.sl__note { margin: 0 0 var(--os-space-md); }
.sl__foot { margin: var(--os-space-lg) 0 0; display: flex; flex-wrap: wrap; align-items: center; gap: var(--os-space-sm); }
@media (max-width: 767px) {
  .sl__item { grid-template-columns: 1fr; gap: var(--os-space-sm); }
  .sl__day { font-size: 1.9rem; }
}

js:
var days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
root.querySelectorAll('.sl__next').forEach(function(el){
  var d=days.indexOf(el.getAttribute('data-weekday')); if(d<0) return;
  var t=new Date(); var add=(d-t.getDay()+7)%7; var n=new Date(t.getFullYear(),t.getMonth(),t.getDate()+add);
  var s=n.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});
  el.textContent='Next: '; var b=document.createElement('b'); b.textContent=s; el.appendChild(b);
});
